import{z as B,x as d,o as l,c as p,q as o,j as i,D as t,d as s,s as E,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"LSM 树作为结构","description":"","frontmatter":{"title":"LSM 树作为结构","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lsm-tree-ds.md","filePath":"cs/lsm-tree-ds.md","lastUpdated":1791413859000}'),m={name:"cs/lsm-tree-ds.md"};function c(A,a,T,h,u,f){const r=d("Mermaid");return l(),p("div",null,[a[2]||(a[2]=o('<h1 id="lsm-树作为结构" tabindex="-1">LSM 树作为结构 <a class="header-anchor" href="#lsm-树作为结构" aria-label="Permalink to &quot;LSM 树作为结构&quot;">​</a></h1><div class="epigraph"><p>内存表写满则冻结刷成有序段；段按层合并，读时从新到旧查直到命中。写变顺序 I/O，读付放大。</p><footer>—— 据 O&#39;Neil, Cheng, Gawlick and O&#39;Neil, The Log-Structured Merge-Tree, Acta Informatica 1996；[WAL](/cs/wal) 课序中的日志思想整理</footer></div><p><a href="/cs/cache-oblivious">上一课</a> 优化未知 \\(B\\) 的读布局。更新密集时原地 B 树随机写贵。<a href="/cs/wal">WAL</a> 已说明先日志。<a href="/cs/bplus-split">B+ 分裂</a> 是原地页改。本课不重讲事务。缺口是把 LSM <strong>当成字典结构</strong>：memtable + 不可变 SSTable 层。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>put</code> 很高、<code>get</code> 可接受延迟。LSM：插入进内存有序表（树或跳表）；满则刷盘成有序文件。读：先 memtable，再各层，用布隆跳过文件。<a href="/cs/bloom-filter">布隆</a> 在此当过滤器，不是本课新发明。合并（compaction）把多层归并，消墓碑。缺口是<strong>用追加与归并代替原地裂页</strong>，代价从写放大、读放大、空间放大三维写合同。</p><p><span class="marginnote">直觉类比：LSM 像厨房里摞餐盘——新盘子永远放最上面一摞，摞满整摞端走（刷盘成段）；定期把几摞归并成更大的整齐一摞（compaction）。找盘子要从上往下翻（读放大），但每摞内部按编号排好，可以二分。</span></p><p><span class="marginnote">O&#39;Neil et al., <em>Acta Informatica</em>, 1996。本课停在结构；不重写某引擎调参百科。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>层容量比 \\(T\\)：第 \\(i\\) 层 \\(\\sim T^i\\)。leveled vs tiered 合并策略改变放大。墓碑删除：直到合并到含旧值的层才真正消失。与<a href="/cs/quotient-filter">商过滤器</a> 可作层内索引，点名。</p><p><span class="marginnote">常见误区：初学者容易以为「删除」就是把键从磁盘抹掉。LSM 里删除只是追加一个墓碑标记，旧值仍躺在下层段里，要等 compaction 归并到那一层才真正消失——所以刚删完一批数据，磁盘占用反而可能先变大。</span></p>',10)),(l(),i(n,null,{default:t(()=>[E(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20PUT%5B%22put%22%5D%20--%3E%20MEM%5B%22memtable%22%5D%0A%20%20MEM%20--%3E%20FLUSH%5B%22%E5%86%BB%E7%BB%93%E6%88%90%E6%9C%89%E5%BA%8F%E6%AE%B5%22%5D%0A%20%20FLUSH%20--%3E%20COMP%5B%22%E5%88%86%E5%B1%82%20compaction%22%5D%0A%20%20GET%5B%22get%22%5D%20--%3E%20NEW%5B%22%E4%BB%8E%E6%96%B0%E5%B1%82%E6%9F%A5%E5%88%B0%E6%97%A7%E5%B1%82%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与路径复制：磁盘段不可变，同「旧版本共享」；memtable 可变。与缓存无关：LSM 参数 \\(T\\) 显式。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"点查最坏碰多层，故 Bloom 与索引块。范围扫描要归并多路迭代器。本课是 CS 结构，不把云厂商产品名当算法。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"数字实例：\\(T=10\\) 时数据量逐层放大 10 倍——10 MB、100 MB、1 GB、10 GB、100 GB、1 TB，存 1 TB 只需约 5–6 层。leveled 下层数就是点查最坏要打开的文件数上界（再加 L0 重叠数），所以 \\(T\\) 同时决定了读放大与写放大。")],-1)),(l(),i(n,null,{default:t(()=>[E(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E5%B1%82%E5%AE%B9%E9%87%8F%E6%AF%94%20T%22%5D%20--%3E%20G%5B%22%E7%AC%AC%20i%20%E5%B1%82%E5%AE%B9%E9%87%8F%20%E2%89%88%20T%5Ei%22%5D%0A%20%20G%20--%3E%20EX%5B%22T%3D10%3A%2010MB%20%E2%86%92%20100MB%20%E2%86%92%201GB%20%E2%86%92%2010GB%20%E2%86%92%20...%22%5D%0A%20%20EX%20--%3E%20DEPTH%5B%22%E5%B1%82%E6%95%B0%20%E2%89%88%20log_T%20%E6%95%B0%E6%8D%AE%E9%87%8F%2C%201TB%20%E7%BA%A6%205%20%E5%B1%82%22%5D%0A%20%20DEPTH%20--%3E%20READ%5B%22%E7%82%B9%E6%9F%A5%E6%9C%80%E5%9D%8F%E7%A2%B0%20%E5%B1%82%E6%95%B0%20%2B%20L0%20%E9%87%8D%E5%8F%A0%20%E4%B8%AA%E6%96%87%E4%BB%B6%22%5D%0A%20%20READ%20--%3E%20BLOOM%5B%22%E5%B8%83%E9%9A%86%E6%8A%8A%E6%AF%8F%E5%B1%82%E7%9A%84%20I%2FO%20%E6%A6%82%E7%8E%87%E5%8E%8B%E5%B0%8F%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p>无锁内存队列下一课回到共享内存，不刷盘。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 RocksDB 调参当正文。并发内存字典用哈希表/跳表，CAS 队列另讲。</p><p>后课默认：写优化外存映射可用 LSM。无锁 FIFO 用 Michael–Scott 队列。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LSM：内存表 + 不可变有序段 + 合并。</li><li>写顺序化，读/写/空间放大互换。</li><li>下一课共享内存无锁队列。</li><li>出处：O&#39;Neil, Cheng, Gawlick and O&#39;Neil, 1996。</li></ul>',6))])}const M=B(m,[["render",c]]);export{D as __pageData,M as default};
